Object.assign(SNIP,{"h11no": "int dai = 0;\nfor (int tam = 0; tam < n; tam++)\n    for (int chan = 0; chan <= 1; chan++) {      // chan = 0: độ dài lẻ; chan = 1: độ dài chẵn\n        int l = tam, r = tam + chan;\n        while (l >= 0 && r < n && s[l] == s[r]) { l--; r++; }\n        dai = max(dai, r - l - 1);             // đoạn đối xứng là s[l + 1 .. r - 1]\n    }", "h11cong": "string cong(string a, string b) {\n    string kq = \"\";\n    int i = a.size() - 1, j = b.size() - 1, nho = 0;\n    while (i >= 0 || j >= 0 || nho > 0) {\n        int t = nho;\n        if (i >= 0) t += a[i--] - '0';\n        if (j >= 0) t += b[j--] - '0';\n        kq += (char)('0' + t % 10);\n        nho = t / 10;\n    }\n    reverse(kq.begin(), kq.end());\n    return kq;\n}"});PRESET_NOTES["l11"]={"Ví dụ: Kiểm tra xâu đối xứng": "Hai con trỏ tiến vào giữa; gặp một cặp khác nhau là dừng ngay.", "Ví dụ: Chuẩn hóa họ tên": "Bỏ mọi dấu cách, chỉ thêm đúng một dấu cách trước mỗi từ (trừ từ đầu). Chữ đầu từ viết hoa, còn lại viết thường. Dấu ngoặc vuông giúp thấy rõ không còn dấu cách ở hai đầu.", "Ví dụ: Cộng hai số lớn": "10²⁰ − 1 cộng 1 tràn mọi kiểu số nguyên của C++, nhưng cộng theo xâu thì không giới hạn. Vòng lặp chạy thêm một lần khi còn nhớ ở cuối."};EX_HINTS["l11"]=[["Code mẫu thử mọi đoạn rồi kiểm tra: O(n³).", "Nở từ tâm: 2n − 1 tâm (ký tự hoặc khe giữa hai ký tự), mỗi tâm nở ra khi hai đầu còn bằng nhau.", "Đoạn tìm được là s[l + 1 .. r − 1], độ dài r − l − 1."], ["Đọc cả dòng bằng getline (cin >> chỉ đọc một từ).", "Đi qua từng ký tự: gặp dấu cách thì đánh dấu “ký tự sau là đầu từ”; gặp chữ thì nếu là đầu từ và kết quả chưa rỗng, thêm một dấu cách trước.", "Chữ đầu từ toupper, còn lại tolower."], ["long long chỉ chứa khoảng 19 chữ số.", "Cộng từ cuối xâu (hàng đơn vị) về đầu, mang theo số nhớ; còn nhớ ở cuối thì thêm chữ số 1.", "Ghép kết quả ngược rồi reverse."]];
