const PR11=[{label:"Ví dụ: Kiểm tra xâu đối xứng",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    string s = \"racecar\";\n    int l = 0, r = s.size() - 1;\n    bool ok = true;\n    while (l < r) {\n        if (s[l] != s[r]) { ok = false; break; }\n        l++;\n        r--;\n    }\n    cout << s << (ok ? \" doi xung\" : \" khong doi xung\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["l","r"]},{type:"vars",names:["ok"]}]},{label:"Ví dụ: Chuẩn hóa họ tên",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    string s = \"  nGUYEN   van   an \", kq = \"\";\n    bool dauTu = true;                     // ký tự tiếp theo có phải chữ đầu của một từ\n    for (char c : s) {\n        if (c == ' ') { dauTu = true; continue; }\n        if (dauTu && !kq.empty()) kq += ' ';   // một dấu cách giữa hai từ\n        kq += dauTu ? (char)toupper(c) : (char)tolower(c);\n        dauTu = false;\n    }\n    cout << \"[\" << kq << \"]\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["c","dauTu","kq"]}]},{label:"Ví dụ: Cộng hai số lớn",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nstring cong(string a, string b) {\n    string kq = \"\";\n    int i = a.size() - 1, j = b.size() - 1, nho = 0;\n    while (i >= 0 || j >= 0 || nho > 0) {\n        int t = nho;\n        if (i >= 0) t += a[i--] - '0';\n        if (j >= 0) t += b[j--] - '0';\n        kq += (char)('0' + t % 10);\n        nho = t / 10;\n    }\n    reverse(kq.begin(), kq.end());\n    return kq;\n}\n\nint main() {\n    cout << cong(\"99999999999999999999\", \"1\") << \"\\n\";\n    cout << cong(\"123\", \"989\") << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["i","j","t","nho","kq"]}]}];
